<section class="page-intro shell"><span class="eyebrow">ALLSTORE CATALOG</span><h1>পছন্দ খুঁজে নিন।</h1><p>প্রতিদিনের দরকারি পণ্য, এক জায়গায় বেছে নেওয়া।</p><form class="shop-filters" method="get" action="/shop"><label class="sr-only" for="filter-q">পণ্য খুঁজুন</label><input id="filter-q" type="search" name="q" value="<?= e($data['search']) ?>" placeholder="নাম, SKU বা শব্দ দিয়ে খুঁজুন"><label class="sr-only" for="filter-category">বিভাগ</label><select id="filter-category" name="category"><option value="">সব বিভাগ</option><?php foreach (($data['categories'] ?? []) as $category): ?><option value="<?= e($category['slug']) ?>" <?= $data['category'] === $category['slug'] ? 'selected' : '' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select><button class="button button-green" type="submit">খুঁজুন</button></form></section>
